from fractions import Fraction as F
from itertools import product
from math import factorial

# Frozen rational parameters
A=F(1939,1000)
B=F(2795,1000)
r=F(623,125)          # 4.984
nu=F(997,200)         # 4.985 = 1+s
s=nu-1
q=r/nu                # 4984/4985
c=F(6083,10000)       # 0.6083
rho=F(857,500)        # 1.714
beta_hat=F(9997,10000)

dirs=((1,0),(-1,0),(0,1),(0,-1))
w=(A,1/A,B,1/B)

# Six-step words whose seven visited vertices are distinct.
states=[]
for word in product(range(4), repeat=6):
    x=y=0
    seen={(0,0)}
    ok=True
    for d in word:
        dx,dy=dirs[d]
        x+=dx; y+=dy
        if (x,y) in seen:
            ok=False; break
        seen.add((x,y))
    if ok:
        states.append(word)
idx={word:i for i,word in enumerate(states)}
trans=[[] for _ in states]
for i,word in enumerate(states):
    for d in range(4):
        nw=word[1:]+(d,)
        j=idx.get(nw)
        if j is not None:
            trans[i].append((j,d))

assert len(states)==780
assert sum(len(t) for t in trans)==2172

